# ============================================================
#  patch_V668.1.ps1  -  BJH Revenue Dashboard
#  V668.1 Sales back to its own column (SC/SP Quotation)
#  run:  cd C:\bjh-dashboard ;  .\go.ps1
# ============================================================
$ErrorActionPreference = 'Stop'
$NEWVER  = 'V668.1'
$BASEVER = 'V668.0'
$MSG     = 'V668.1 Sales back to its own column (SC/SP Quotation)'
$DEPID   = 'AKfycbzO7LW1DPUOzosAxpZsJPvX8PoW4eJ8rDHuZI-GXwHpT9yXDERnrEdPVvdOoffQLVF-kw'
$STAMP   = Get-Date -Format 'yyyyMMdd_HHmmss'
$ROOT    = 'C:\bjh-dashboard'

Set-Location $ROOT
if (-not (Test-Path "$ROOT\Deploy")) { New-Item -ItemType Directory -Path "$ROOT\Deploy" | Out-Null }
Start-Transcript -Path "$ROOT\Deploy\patch_${NEWVER}_$STAMP.log" -Force | Out-Null

# --- portable node / git (same as start.ps1) ---
$NODE = 'C:\Users\pongsakr\Downloads\node\node'
$NPMG = "$env:USERPROFILE\.npm-global"
$GIT  = 'C:\Users\pongsakr\Downloads\PortableGit\cmd'
$env:Path = "$NODE;$NPMG;$GIT;" + $env:Path

Write-Host ''
Write-Host "=== BJH patch $NEWVER ===" -ForegroundColor Cyan

# ============ GUARD : base version ============
$ovTxt = [IO.File]::ReadAllText("$ROOT\overrides.html", [Text.Encoding]::UTF8)
if ($ovTxt -notmatch "_BUILD_VER='V668\.0'") {
  $cur = ([regex]::Match($ovTxt, "_BUILD_VER='([^']+)'")).Groups[1].Value
  Write-Host "BASE MISMATCH : found '$cur' , expected '$BASEVER'" -ForegroundColor Red
  Stop-Transcript | Out-Null ; exit 1
}
Write-Host "guard ok : base $BASEVER" -ForegroundColor Green

function Write-Payload([string]$Name, [string]$B64, [string]$Sha) {
  $gz    = [Convert]::FromBase64String(($B64 -replace '\s',''))
  $msIn  = New-Object IO.MemoryStream(,$gz)
  $msOut = New-Object IO.MemoryStream
  $gzs   = New-Object IO.Compression.GzipStream($msIn, [IO.Compression.CompressionMode]::Decompress)
  $gzs.CopyTo($msOut) ; $gzs.Dispose() ; $msIn.Dispose()
  $bytes = $msOut.ToArray() ; $msOut.Dispose()
  $sha256 = [Security.Cryptography.SHA256]::Create()
  $h = (($sha256.ComputeHash($bytes) | ForEach-Object { $_.ToString('x2') }) -join '').ToUpper()
  $sha256.Dispose()
  if ($h -ne $Sha) { throw "SHA mismatch $Name : $h != $Sha" }
  $dst = Join-Path $ROOT $Name
  if (Test-Path $dst) { Copy-Item $dst "$dst.bak_$STAMP" -Force }
  [IO.File]::WriteAllBytes($dst, $bytes)
  Write-Host ('  wrote ' + $Name + '  ' + [math]::Round($bytes.Length/1KB) + ' KB  sha ok') -ForegroundColor Green
}

